style.css:
/* Fondo general */
body {
    background-color: #eaf6fb !important;
    color: #2f5f6f !important;
}

/* Contenedores y tarjetas */
div, section, article, main {
    background-color: #dff1f7 !important;
    border-radius: 12px !important;
}

/* Headers y barras */
header, nav {
    background-color: #c9ecf5 !important;
}

/* Texto */
h1, h2, h3, h4, h5, h6 {
    color: #2f5f6f !important;
}

p, span, label {
    color: #4f7f8f !important;
}

/* Botones */
button, input[type="button"], input[type="submit"] {
    background-color: #a7dcec !important;
    color: #2f5f6f !important;
    border-radius: 8px !important;
    border: none !important;
    transition: all 0.3s ease;
}

button:hover {
    background-color: #8fcfe3 !important;
}

/* Inputs */
input, textarea, select {
    background-color: #eaf6fb !important;
    color: #2f5f6f !important;
    border: 1px solid #a7dcec !important;
    border-radius: 6px !important;
}

/* Links */
a {
    color: #5fbcd3 !important;
}

a:hover {
    color: #3aa6c1 !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #eaf6fb;
}

::-webkit-scrollbar-thumb {
    background: #a7dcec;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #8fcfe3;
}
